import static org.junit.Assert.assertEquals;
import java.io.StringReader;
import java.io.StringWriter;
import java.util.HashSet;
import java.util.Set;
import org.junit.Test;
public class WordWrapTest {

    @Test
    public void fromReaderTest() {
        WordWrap.Builder builder = WordWrap.from(new StringReader("This is a test."));
        assertEquals(WordWrap.Builder.class, builder.getClass());
    }

    @Test
    public void fromCStringTest() {
        WordWrap.Builder builder = WordWrap.from("Test string");
        assertEquals(WordWrap.Builder.class, builder.getClass());
    }

    @Test
    public void wordWrapTrimTest() throws Exception {
        String testStr = "This is a long sentence that may need to be wrapped.";
        StringReader reader = new StringReader(testStr);
        StringWriter writer = new StringWriter();
        Set<Character> extraChars = new HashSet<>();
        WordWrap.wordWrap(reader, writer, "\n", 10, CharSequence::length, extraChars, false, false);
        String[] lines = writer.toString().split("\n");
        for (String line : lines) {
            assertEquals(10, line.length());
        }
    }

    @Test
    public void rightTrimTest() {
        CharSequence test = "  Testing..  ";
        CharSequence trimmed = WordWrap.rightTrim(test);
        assertEquals("  Testing..", trimmed.toString());
    }

    @Test
    public void isWhitespaceTest() {
        CharSequence test = "   ";
        boolean result = WordWrap.isWhitespace(test);
        assertEquals(true, result);
    }

    @Test
    public void fromUtf8Test() {
        WordWrap.Builder builder = WordWrap.fromUtf8(new ByteArrayInputStream("test".getBytes()));
        assertEquals(WordWrap.Builder.class, builder.getClass());
    }

    @Test
    public void fromCloseReaderNonClosingTest() {
        WordWrap.Builder builder = WordWrap.from(new StringReader("This is a test."), false);
        assertEquals(WordWrap.Builder.class, builder.getClass());
    }
}
